/**
 * The access levels are mapped to the following values on the platform
 *
 * - `none`: 0
 * - `tracking`: 1
 * - `restricted`: 2
 *
 */
const callerAccessLevels = ['none', 'tracking', 'restricted'] as const

/**
 * Reads a `sys_db_object` access flag from a record. Values can arrive as booleans or as
 * 'true'/'false' strings depending on the source. Anything else - including the empty string an
 * empty XML element parses to - means the flag was never set, and stays undefined so the
 * corresponding property is omitted from the generated Fluent code instead of being asserted
 * as `false`.
 */
function toAccessFlag(shape: Shape): boolean | undefined {
    const value = shape.ifBoolean()?.getValue()
    if (value !== undefined) {
        return value
    }
    switch (shape.ifString()?.getValue().trim().toLowerCase()) {
        case 'true':
            return true
        case 'false':
            return false
        default:
            return undefined
    }
}

